let state = "closed";
let failures = 0;
function result(ok) {
  if (state === "open") return "blocked";
  if (ok) {
    failures = 0;
    state = "closed";
  } else {
    failures++;
    if (state === "half-open" || failures >= 2) state = "open";
  }
  return state;
}
console.log(result(false));
console.log(result(false));
console.log(result(true));
state = "half-open"; // pretend the cooldown has passed
console.log(state);
console.log(result(true));
